import {create} from 'zustand';import {api} from '../services/api';import type {User} from '../types';
type State={user:User|null;loading:boolean;login:(email:string,password:string)=>Promise<void>;logout:()=>Promise<void>;restore:()=>Promise<void>};
export const useAuth=create<State>(set=>({user:null,loading:true,login:async(email,password)=>{const {data}=await api.post('/auth/login',{email,password});set({user:data.user})},logout:async()=>{await api.post('/auth/logout');set({user:null})},restore:async()=>{try{const {data}=await api.get('/auth/me');set({user:data.user,loading:false})}catch{set({user:null,loading:false})}}}));
